transformation Team2Plan
from Team
to Plan

Team -> Plan {
    name := name
    -> tasks {
        forall m in members -> Task {
            name := "task_" + m.name
            -> deps {
                forall o in members such that o.rank < m.rank -> Link {
                    name := m.name + "_after_" + o.name
                    -> via {
                        -> Link { name := "via_" + m.name }
                    }
                }
            }
            -> owner {
                -> Link { name := "own_" + m.name }
            }
        }
    }
}

